'use client';

import { useState } from 'react';
import type { ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from '@/components/ui/input-group';
import { cn } from '../utils/utils';
import { ArrowUpIcon, CheckIcon, MessageCircleQuestionIcon } from '../_shared/icons';

/** The stable values of a decision. The host stores these; the words on the buttons are labels and may be translated. */
export const DECISION_VALUES = ['approve', 'refuse'] as const;
export type DecisionValue = (typeof DECISION_VALUES)[number];

/** A `decision` is a gate or a review: approve or refuse. A `question` takes a choice or free text. */
export type InlineQuestionKind = 'decision' | 'question';

/** `neutral` is flat; `attention` is the warning tint. */
export type InlineQuestionTone = 'neutral' | 'attention';

export type InlineQuestionLabels = { decision: string; question: string; approve: string; refuse: string; send: string; placeholder: string; placeholderMore: string; replyInChat: string; approved: string; refused: string; answered: string };

export const inlineQuestionLabels: InlineQuestionLabels = {
  decision: 'Decision', question: 'Question', approve: 'Approve', refuse: 'Refuse', send: 'Answer', placeholder: 'Type your answer', placeholderMore: 'Or type an answer',
  replyInChat: 'Reply in chat', approved: 'Approved', refused: 'Refused', answered: 'Answered',
};

/** A choice as data: `recommended` is the host's explicit say-so that this one is the suggested answer. Without it, every choice looks the same. */
export type InlineQuestionOption = { label: string; recommended?: boolean };

export type InlineQuestionProps = {
  /** Identifies the question to the host; echoed back by `onAnswer`. */
  id: string;
  kind: InlineQuestionKind;
  /** The question as the agent asked it, in the person's language. */
  text: string;
  /** Who is asking (an agent or a gate), shown small above the question. */
  source?: string;
  /** A `question` with options offers up to four one-tap choices plus a free-text field; without options it is free text only. A `decision` ignores them. A choice is its text, or `{ label, recommended }`; the answer is always the text. All choices are outline buttons; only the first one marked `recommended` is the primary button (never by position). */
  options?: readonly (string | InlineQuestionOption)[];
  /** Most one-tap choices shown (default 4). A longer list is a form, not an inline question. */
  maxOptions?: number;
  /** `false`: choices only, no free-text field (a question with options only). Default true; without options the field always shows. */
  freeText?: boolean;
  /** The host cannot take an answer now (still being written, sending, unavailable): every control is disabled. */
  disabled?: boolean;
  /** A line under the controls, for example why an answer was refused or why answering is unavailable. */
  notice?: ReactNode;
  /** Set once answered: the controls give way to the answer, so the question stays readable in the history. */
  answered?: string;
  /** The block sends nothing. The host posts the answer under the signed-in person's own login, never a shared token. */
  onAnswer: (id: string, value: string) => void; // decision: 'approve' | 'refuse' (stable, never a label); question: the option text or the typed text
  /** Opens the full chat for a longer reply. Shown only when given. */
  onReplyInChat?: () => void;
  labels?: Partial<InlineQuestionLabels>;
  /** Attention is for gates or critical items only. Default `neutral`. */
  tone?: InlineQuestionTone;
  className?: string;
};

const tap = 'min-h-11 md:min-h-8';

/** A waiting question shown where it is mentioned. No border. `tone="neutral"` (default) is flat: no fill, no padding, foreground text, so a list of routine questions stays quiet. `tone="attention"` is a soft warning tint with padding and a chip on the kind label, for a gate or a critical item. */
export function InlineQuestion({ id, kind, text, source, options, answered, onAnswer, onReplyInChat, labels, className, tone = 'neutral', maxOptions = 4, freeText = true, disabled = false, notice }: InlineQuestionProps) {
  const t = { ...inlineQuestionLabels, ...labels };
  const [draft, setDraft] = useState('');
  const decision = kind === 'decision';
  const attention = tone === 'attention';
  const shown = (options ?? []).slice(0, maxOptions).map(option => typeof option === 'string' ? { value: option, label: option, recommended: false } : { value: option.label, label: option.label, recommended: option.recommended === true });
  const choices: readonly { value: string; label: string; primary: boolean }[] = decision
    ? [{ value: DECISION_VALUES[0], label: t.approve, primary: true }, { value: DECISION_VALUES[1], label: t.refuse, primary: false }]
    : shown.map(option => ({ value: option.value, label: option.label, primary: option.recommended && option === shown.find(other => other.recommended) }));
  const showField = !decision && (freeText || choices.length === 0);
  const send = () => { const value = draft.trim(); if (value && !disabled) onAnswer(id, value); };
  if (answered !== undefined) {
    const said = decision && answered === 'approve' ? t.approved : decision && answered === 'refuse' ? t.refused : `${t.answered}: ${answered}`;
    return (
      <div role="group" aria-label={text} className={cn('flex min-w-0 flex-col gap-1 text-muted-foreground', attention && 'p-3', className)}>
        <div className="flex items-start gap-2 text-sm font-medium"><CheckIcon aria-hidden className="mt-0.5 size-4 shrink-0" /><span>{text}</span></div>
        <span className="text-xs">{said}</span>
      </div>
    );
  }
  return (
    <div role="group" aria-label={text} className={cn('flex min-w-0 flex-col gap-2', attention ? 'rounded-(--radius) bg-warning-soft p-3 text-warning-soft-foreground' : 'text-foreground', className)}>
      <div className="flex min-w-0 items-center gap-2 text-xs">
        <span className={attention ? 'rounded-(--radius) bg-card px-2 text-card-foreground' : 'text-muted-foreground'}>{decision ? t.decision : t.question}</span>
        {source ? <span className="truncate opacity-80">{source}</span> : null}
      </div>
      <div className="flex min-w-0 items-start gap-2 text-sm font-medium">
        <MessageCircleQuestionIcon aria-hidden className="mt-0.5 size-4 shrink-0" />
        <span data-testid="question-text" className="min-w-0 [overflow-wrap:anywhere]">{text}</span>
      </div>
      {choices.length > 0 || onReplyInChat ? (
        <div className="flex flex-wrap gap-1">
          {choices.map(choice => (
            <Button key={choice.value} variant={decision ? (choice.primary ? 'default' : 'secondary') : choice.primary ? 'default' : 'outline'} size="sm" className={cn(tap, 'h-auto max-w-full justify-start whitespace-normal text-start [overflow-wrap:anywhere]')} data-testid="question-option" data-option={choice.value} disabled={disabled} onClick={() => onAnswer(id, choice.value)}>{choice.label}</Button>
          ))}
          {onReplyInChat ? <Button variant="ghost" size="sm" className={tap} onClick={onReplyInChat}>{t.replyInChat}</Button> : null}
        </div>
      ) : null}
      {showField ? (
        // One box: the field and the send as a trailing icon button inside it, on the --card fill and the --input edge; the fill and the 44px fit (under md or on a coarse pointer) are this item's `css` in registry.json, scoped by data-slot=question-field (D-1741 will tokenise the 44px). 16px text on a phone so iOS does not zoom.
        <form data-slot="question-field" onSubmit={event => { event.preventDefault(); send(); }}>
          <InputGroup>
            <InputGroupInput data-testid="question-input" disabled={disabled} maxLength={2000} value={draft} onChange={event => setDraft(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && !event.nativeEvent.isComposing && event.keyCode !== 229) { event.preventDefault(); send(); } }} placeholder={choices.length ? t.placeholderMore : t.placeholder} aria-label={t.placeholder} className="h-full text-base md:text-sm" />
            <InputGroupAddon align="inline-end">
              <InputGroupButton type="submit" size="icon-sm" variant="default" aria-label={t.send} data-testid="question-submit" disabled={disabled || !draft.trim()}><ArrowUpIcon aria-hidden="true" /></InputGroupButton>
            </InputGroupAddon>
          </InputGroup>
        </form>
      ) : null}
      {notice ? <div className="text-sm">{notice}</div> : null}
    </div>
  );
}
